"use strict";exports.id=776,exports.ids=[776],exports.modules={82776:(a,b,c)=>{c.d(b,{DRUG_DB:()=>d});let d=[{id:"paracetamol",genericName:"Paracetamol (Acetaminophen)",brandNames:["Panadol","Tylenol","Sanmol","Biogesic"],drugClass:"Analgesic / Antipyretic",indications:{en:"Mild to moderate pain, fever.",id:"Nyeri ringan hingga sedang, demam."},contraindications:{en:"Severe hepatic impairment.",id:"Gangguan hati berat."},dosing:{dosePerKg:15,unit:"mg",maxDose:1e3,frequency:"q4-6h PRN",notes:{en:"Max 75 mg/kg/day or 4g/day. For fever/pain.",id:"Maks. 75 mg/kg/hari atau 4g/hari. Untuk demam/nyeri."}}},{id:"ibuprofen",genericName:"Ibuprofen",brandNames:["Advil","Motrin","Proris","Farsifen"],drugClass:"NSAID",indications:{en:"Mild to moderate pain, inflammation, fever.",id:"Nyeri ringan hingga sedang, peradangan, demam."},contraindications:{en:"Active GI bleeding, history of asthma triggered by NSAIDs.",id:"Pendarahan GI aktif, riwayat asma yang dipicu NSAID."},dosing:{dosePerKg:10,unit:"mg",maxDose:800,frequency:"q6-8h PRN",notes:{en:"Max 40 mg/kg/day or 3.2g/day. Take with food.",id:"Maks. 40 mg/kg/hari atau 3.2g/hari. Konsumsi saat makan."}}},{id:"amoxicillin",genericName:"Amoxicillin",brandNames:["Amoxil","Amoxsan","Lapimox"],drugClass:"Antibiotic",indications:{en:"Bacterial infections (e.g., otitis media, strep throat).",id:"Infeksi bakteri (misal: otitis media, radang tenggorokan)."},contraindications:{en:"Hypersensitivity to penicillins.",id:"Hipersensitivitas terhadap penisilin."},dosing:{dosePerKg:40,unit:"mg",maxDose:1e3,frequency:"q8h or q12h",notes:{en:"Dosing ranges from 40-90 mg/kg/day divided. Check local guidelines.",id:"Dosis berkisar antara 40-90 mg/kg/hari terbagi. Cek pedoman lokal."}}},{id:"cetirizine",genericName:"Cetirizine",brandNames:["Zyrtec","Incidal","Cetirizine OGB"],drugClass:"Antihistamine",indications:{en:"Allergic rhinitis, urticaria.",id:"Rinitis alergi, urtikaria (biduran)."},contraindications:{en:"Severe renal impairment.",id:"Gangguan ginjal berat."},dosing:{dosePerKg:.25,unit:"mg",maxDose:10,frequency:"q24h",notes:{en:"Usually given once daily. Adjust in renal failure.",id:"Biasanya diberikan sekali sehari. Sesuaikan pada gagal ginjal."}}},{id:"propofol",genericName:"Propofol",brandNames:["Diprivan","Recofol"],drugClass:"General Anesthetic",indications:{en:"Induction and maintenance of general anesthesia, sedation.",id:"Induksi dan pemeliharaan anestesi umum, sedasi."},contraindications:{en:"Hypersensitivity to propofol, egg, or soy products.",id:"Hipersensitivitas terhadap propofol, produk telur, atau kedelai."},dosing:{dosePerKg:2,unit:"mg",maxDose:200,frequency:"single dose for induction",notes:{en:"Induction 1.5-2.5 mg/kg IV. Adjust in elderly/compromised.",id:"Induksi 1.5-2.5 mg/kg IV. Sesuaikan pada lansia/kondisi lemah."}}},{id:"ketamine",genericName:"Ketamine",brandNames:["Ketalar","Ivanes"],drugClass:"Dissociative Anesthetic",indications:{en:"Induction and maintenance of general anesthesia, acute pain.",id:"Induksi dan pemeliharaan anestesi umum, nyeri akut."},contraindications:{en:"Conditions where an increase in blood pressure would be hazardous.",id:"Kondisi di mana peningkatan tekanan darah dapat berbahaya."},dosing:{dosePerKg:1.5,unit:"mg",maxDose:150,frequency:"single dose for induction",notes:{en:"Induction 1-2 mg/kg IV or 4-10 mg/kg IM. Can cause emergence delirium.",id:"Induksi 1-2 mg/kg IV atau 4-10 mg/kg IM. Dapat menyebabkan delirium siuman."}}},{id:"fentanyl",genericName:"Fentanyl",brandNames:["Sublimaze","Durogesic"],drugClass:"Opioid Analgesic",indications:{en:"Analgesia during anesthesia, severe pain.",id:"Analgesia selama anestesi, nyeri hebat."},contraindications:{en:"Significant respiratory depression, acute/severe asthma.",id:"Depresi pernapasan signifikan, asma akut/berat."},dosing:{dosePerKg:.002,unit:"mg",maxDose:.1,frequency:"PRN",notes:{en:"1-2 mcg/kg IV for analgesia. High doses cause chest wall rigidity.",id:"1-2 mcg/kg IV untuk analgesia. Dosis tinggi menyebabkan kekakuan dinding dada."}}},{id:"midazolam",genericName:"Midazolam",brandNames:["Versed","Dormicum","Miloz"],drugClass:"Benzodiazepine",indications:{en:"Preoperative sedation, anxiolysis, amnesia.",id:"Sedasi prabedah, ansiolisis, amnesia."},contraindications:{en:"Acute narrow-angle glaucoma, severe respiratory insufficiency.",id:"Glaukoma sudut sempit akut, insufisiensi pernapasan berat."},dosing:{dosePerKg:.05,unit:"mg",maxDose:5,frequency:"single dose",notes:{en:"0.02-0.05 mg/kg IV for premedication. Reduce dose in elderly.",id:"0.02-0.05 mg/kg IV untuk premedikasi. Kurangi dosis pada lansia."}}},{id:"ephedrine",genericName:"Ephedrine",brandNames:["Akovaz","Corphedrine"],drugClass:"Vasopressor",indications:{en:"Treatment of anesthesia-induced hypotension.",id:"Pengobatan hipotensi yang diinduksi anestesi."},contraindications:{en:"Closed-angle glaucoma, non-anaphylactic shock.",id:"Glaukoma sudut tertutup, syok non-anafilaksis."},dosing:{dosePerKg:.1,unit:"mg",maxDose:10,frequency:"PRN",notes:{en:"5-10 mg IV bolus. Tachyphylaxis can occur with repeated doses.",id:"Bolus IV 5-10 mg. Takifilaksis dapat terjadi dengan dosis berulang."}}},{id:"ondansetron",genericName:"Ondansetron",brandNames:["Zofran","Narfoz","Vomceran"],drugClass:"Antiemetic",indications:{en:"Prevention of postoperative nausea and vomiting (PONV).",id:"Pencegahan mual dan muntah pascaoperasi (PONV)."},contraindications:{en:"Concomitant use with apomorphine.",id:"Penggunaan bersamaan dengan apomorfin."},dosing:{dosePerKg:.1,unit:"mg",maxDose:8,frequency:"q8h",notes:{en:"4-8 mg IV/PO for PONV prophylaxis. Can prolong QT interval.",id:"4-8 mg IV/PO untuk profilaksis PONV. Dapat memperpanjang interval QT."}}},{id:"amlodipine",genericName:"Amlodipine",brandNames:["Norvasc","Amlodipine OGB","Tensivask"],drugClass:"Calcium Channel Blocker",indications:{en:"Hypertension, chronic stable angina.",id:"Hipertensi, angina stabil kronis."},contraindications:{en:"Severe hypotension, shock.",id:"Hipotensi berat, syok."},dosing:{dosePerKg:.1,unit:"mg",maxDose:10,frequency:"q24h",notes:{en:"Adult dose 5-10 mg once daily. May cause peripheral edema.",id:"Dosis dewasa 5-10 mg sekali sehari. Dapat menyebabkan edema perifer."}}},{id:"metformin",genericName:"Metformin",brandNames:["Glucophage","Gludepatic","Metformin OGB"],drugClass:"Biguanide Antidiabetic",indications:{en:"Type 2 Diabetes Mellitus.",id:"Diabetes Melitus Tipe 2."},contraindications:{en:"Severe renal impairment (eGFR <30), metabolic acidosis.",id:"Gangguan ginjal berat (eGFR <30), asidosis metabolik."},dosing:{dosePerKg:10,unit:"mg",maxDose:2e3,frequency:"q12h or q8h",notes:{en:"Take with meals to reduce GI upset. Monitor B12 and renal function.",id:"Konsumsi saat makan untuk mengurangi gangguan GI. Pantau B12 dan fungsi ginjal."}}},{id:"omeprazole",genericName:"Omeprazole",brandNames:["Prilosec","Losec","Pumpitor"],drugClass:"Proton Pump Inhibitor (PPI)",indications:{en:"GERD, peptic ulcer disease, H. pylori eradication.",id:"GERD, penyakit ulkus peptikum, eradikasi H. pylori."},contraindications:{en:"Hypersensitivity to substituted benzimidazoles.",id:"Hipersensitivitas terhadap benzimidazol tersubstitusi."},dosing:{dosePerKg:.5,unit:"mg",maxDose:40,frequency:"q24h",notes:{en:"20-40 mg PO/IV daily. Give 30-60 min before a meal.",id:"20-40 mg PO/IV per hari. Berikan 30-60 menit sebelum makan."}}},{id:"simvastatin",genericName:"Simvastatin",brandNames:["Zocor","Simvastatin OGB","Detrovel"],drugClass:"HMG-CoA Reductase Inhibitor",indications:{en:"Hyperlipidemia, cardiovascular event risk reduction.",id:"Hiperlipidemia, pengurangan risiko kejadian kardiovaskular."},contraindications:{en:"Active liver disease, pregnancy.",id:"Penyakit hati aktif, kehamilan."},dosing:{dosePerKg:.5,unit:"mg",maxDose:40,frequency:"q24h",notes:{en:"10-40 mg taken in the evening. Risk of myopathy increases at 80 mg.",id:"10-40 mg diminum pada malam hari. Risiko miopati meningkat pada dosis 80 mg."}}},{id:"salbutamol",genericName:"Salbutamol (Albuterol)",brandNames:["Ventolin","Lasal","Fartolin"],drugClass:"Short-acting Beta2 Agonist (SABA)",indications:{en:"Bronchospasm in asthma and COPD.",id:"Bronkospasme pada asma dan PPOK."},contraindications:{en:"Severe hypersensitivity to the drug or formulation components.",id:"Hipersensitivitas berat terhadap obat atau komponen formulasi."},dosing:{dosePerKg:.15,unit:"mg",maxDose:5,frequency:"PRN",notes:{en:"Nebulization: 2.5 - 5 mg PRN for acute attacks. May cause tachycardia.",id:"Nebulisasi: 2.5 - 5 mg PRN untuk serangan akut. Dapat menyebabkan takikardia."}}},{id:"ciprofloxacin",genericName:"Ciprofloxacin",brandNames:["Cipro","Baquinor","Ciprofloxacin OGB"],drugClass:"Fluoroquinolone Antibiotic",indications:{en:"UTI, typhoid fever, severe gastroenteritis, respiratory infections.",id:"ISK, demam tifoid, gastroenteritis berat, infeksi pernapasan."},contraindications:{en:"Concurrent tizanidine administration, history of myasthenia gravis.",id:"Pemberian bersamaan tizanidine, riwayat miastenia gravis."},dosing:{dosePerKg:10,unit:"mg",maxDose:1500,frequency:"q12h",notes:{en:"Adults: 500 mg PO BID. Risk of tendon rupture and QT prolongation.",id:"Dewasa: 500 mg PO dua kali sehari. Risiko ruptur tendon dan perpanjangan QT."}}},{id:"dexamethasone",genericName:"Dexamethasone",brandNames:["Decadron","Kalmethasone","Dexa-M"],drugClass:"Corticosteroid",indications:{en:"Inflammatory conditions, severe allergic reactions, PONV prophylaxis.",id:"Kondisi inflamasi, reaksi alergi berat, profilaksis PONV."},contraindications:{en:"Systemic fungal infections, cerebral malaria.",id:"Infeksi jamur sistemik, malaria serebral."},dosing:{dosePerKg:.1,unit:"mg",maxDose:10,frequency:"q24h or single dose",notes:{en:"4-8 mg IV/PO. Tapering required for prolonged use.",id:"4-8 mg IV/PO. Penurunan dosis bertahap (tapering) diperlukan untuk penggunaan jangka panjang."}}},{id:"losartan",genericName:"Losartan",brandNames:["Cozaar","Acetensa","Losartan OGB"],drugClass:"Angiotensin II Receptor Blocker (ARB)",indications:{en:"Hypertension, diabetic nephropathy.",id:"Hipertensi, nefropati diabetik."},contraindications:{en:"Pregnancy (2nd and 3rd trimesters), concurrent aliskiren in diabetes.",id:"Kehamilan (trimester ke-2 dan ke-3), penggunaan bersamaan aliskiren pada diabetes."},dosing:{dosePerKg:.7,unit:"mg",maxDose:100,frequency:"q24h",notes:{en:"Starting dose 50 mg daily. Monitor potassium and renal function.",id:"Dosis awal 50 mg per hari. Pantau kalium dan fungsi ginjal."}}},{id:"aspirin",genericName:"Aspirin",brandNames:["Aspilets","Cardio Aspirin","Bayer"],drugClass:"Antiplatelet / NSAID",indications:{en:"Secondary prevention of MI and stroke, mild pain.",id:"Pencegahan sekunder infark miokard dan stroke, nyeri ringan."},contraindications:{en:"Active bleeding, hemophilia, asthma exacerbated by NSAIDs.",id:"Pendarahan aktif, hemofilia, asma yang diperburuk oleh NSAID."},dosing:{dosePerKg:1,unit:"mg",maxDose:320,frequency:"q24h",notes:{en:"80-160 mg daily for cardioprotection. 300-320 mg for acute MI.",id:"80-160 mg per hari untuk kardioproteksi. 300-320 mg untuk infark miokard akut."}}},{id:"azithromycin",genericName:"Azithromycin",brandNames:["Zithromax","Zmax","Meiact"],drugClass:"Macrolide Antibiotic",indications:{en:"Respiratory tract infections, chlamydia, typhoid fever.",id:"Infeksi saluran pernapasan, klamidia, demam tifoid."},contraindications:{en:"History of cholestatic jaundice or hepatic dysfunction with prior use.",id:"Riwayat ikterus kolestatik atau disfungsi hati dengan penggunaan sebelumnya."},dosing:{dosePerKg:10,unit:"mg",maxDose:500,frequency:"q24h",notes:{en:"Adults: 500 mg day 1, then 250 mg for 4 days. May prolong QT interval.",id:"Dewasa: 500 mg hari 1, lalu 250 mg selama 4 hari. Dapat memperpanjang interval QT."}}},{id:"ceftriaxone",genericName:"Ceftriaxone",brandNames:["Rocephin","Broadced","Terfacef"],drugClass:"3rd Generation Cephalosporin",indications:{en:"Severe infections (meningitis, pneumonia, sepsis, gonorrhea).",id:"Infeksi berat (meningitis, pneumonia, sepsis, gonore)."},contraindications:{en:"Hyperbilirubinemic neonates, concurrent IV calcium in neonates.",id:"Neonatus hiperbilirubinemia, kalsium IV bersamaan pada neonatus."},dosing:{dosePerKg:50,unit:"mg",maxDose:4e3,frequency:"q12h or q24h",notes:{en:"Adults: 1-2g IV/IM daily. Up to 4g/day for meningitis.",id:"Dewasa: 1-2g IV/IM per hari. Hingga 4g/hari untuk meningitis."}}},{id:"cefixime",genericName:"Cefixime",brandNames:["Suprax","Cefspan","Sporetik"],drugClass:"3rd Generation Cephalosporin",indications:{en:"Uncomplicated UTI, otitis media, gonorrhea, typhoid.",id:"ISK tanpa komplikasi, otitis media, gonore, tifoid."},contraindications:{en:"Hypersensitivity to cephalosporins.",id:"Hipersensitivitas terhadap sefalosporin."},dosing:{dosePerKg:8,unit:"mg",maxDose:400,frequency:"q12h or q24h",notes:{en:"Adults: 400 mg daily or 200 mg BID.",id:"Dewasa: 400 mg sehari atau 200 mg dua kali sehari."}}},{id:"doxycycline",genericName:"Doxycycline",brandNames:["Vibramycin","Doxy","Siklon"],drugClass:"Tetracycline Antibiotic",indications:{en:"Atypical pneumonia, syphilis, Lyme disease, acne.",id:"Pneumonia atipikal, sifilis, penyakit Lyme, jerawat."},contraindications:{en:"Pregnancy, children < 8 years (due to tooth discoloration).",id:"Kehamilan, anak < 8 tahun (karena perubahan warna gigi)."},dosing:{dosePerKg:2,unit:"mg",maxDose:200,frequency:"q12h",notes:{en:"100 mg BID. Take with full glass of water, remain upright for 30 mins.",id:"100 mg dua kali sehari. Minum dengan segelas air penuh, tetap tegak selama 30 menit."}}},{id:"clindamycin",genericName:"Clindamycin",brandNames:["Cleocin","Dalacin","Clinidac"],drugClass:"Lincosamide Antibiotic",indications:{en:"Skin/soft tissue infections, anaerobic infections, osteomyelitis.",id:"Infeksi kulit/jaringan lunak, infeksi anaerobik, osteomielitis."},contraindications:{en:"History of regional enteritis, ulcerative colitis, or C. diff colitis.",id:"Riwayat enteritis regional, kolitis ulserativa, atau kolitis C. diff."},dosing:{dosePerKg:10,unit:"mg",maxDose:1800,frequency:"q6h or q8h",notes:{en:"Adults: 150-450 mg PO q6h. High risk for C. diff infection.",id:"Dewasa: 150-450 mg PO setiap 6 jam. Risiko tinggi infeksi C. diff."}}},{id:"levofloxacin",genericName:"Levofloxacin",brandNames:["Levaquin","Cravit","Levofloxacin OGB"],drugClass:"Fluoroquinolone Antibiotic",indications:{en:"CAP, complicated UTI, pyelonephritis, skin infections.",id:"Pneumonia (CAP), ISK terkomplikasi, pielonefritis, infeksi kulit."},contraindications:{en:"History of myasthenia gravis, hypersensitivity to fluoroquinolones.",id:"Riwayat miastenia gravis, hipersensitivitas terhadap fluorokuinolon."},dosing:{dosePerKg:8,unit:"mg",maxDose:750,frequency:"q24h",notes:{en:"Adults: 500-750 mg daily. Adjust in renal impairment.",id:"Dewasa: 500-750 mg per hari. Sesuaikan pada gangguan ginjal."}}},{id:"metronidazole",genericName:"Metronidazole",brandNames:["Flagyl","Trichodazol","Metronidazole OGB"],drugClass:"Nitroimidazole Antibiotic",indications:{en:"Anaerobic infections, C. diff colitis, Trichomoniasis, Amoebiasis.",id:"Infeksi anaerob, kolitis C. diff, Trikomoniasis, Amebiasis."},contraindications:{en:"First trimester of pregnancy, use of alcohol (disulfiram reaction).",id:"Trimester pertama kehamilan, penggunaan alkohol (reaksi disulfiram)."},dosing:{dosePerKg:10,unit:"mg",maxDose:2e3,frequency:"q8h",notes:{en:"Adults: 500 mg PO/IV q8h. Avoid alcohol during and 3 days after.",id:"Dewasa: 500 mg PO/IV setiap 8 jam. Hindari alkohol selama dan 3 hari setelahnya."}}},{id:"meropenem",genericName:"Meropenem",brandNames:["Merrem","Merem","Ronem"],drugClass:"Carbapenem Antibiotic",indications:{en:"Severe healthcare-associated infections, meningitis, complicated intra-abdominal infections.",id:"Infeksi terkait layanan kesehatan yang parah, meningitis, infeksi intra-abdomen terkomplikasi."},contraindications:{en:"Anaphylaxis to beta-lactams.",id:"Anafilaksis terhadap beta-laktam."},dosing:{dosePerKg:20,unit:"mg",maxDose:6e3,frequency:"q8h",notes:{en:"Adults: 500mg-1g IV q8h (up to 2g q8h for meningitis).",id:"Dewasa: 500mg-1g IV setiap 8 jam (hingga 2g setiap 8 jam untuk meningitis)."}}},{id:"vancomycin",genericName:"Vancomycin",brandNames:["Vancocin","Vancocin CP"],drugClass:"Glycopeptide Antibiotic",indications:{en:"MRSA infections, severe C. diff colitis (oral).",id:"Infeksi MRSA, kolitis C. diff berat (oral)."},contraindications:{en:"Hypersensitivity to vancomycin.",id:"Hipersensitivitas terhadap vankomisin."},dosing:{dosePerKg:15,unit:"mg",maxDose:4e3,frequency:"q12h or q8h",notes:{en:"Adults: 15-20 mg/kg IV q8-12h. Monitor trough levels. Slow infusion to prevent red man syndrome.",id:"Dewasa: 15-20 mg/kg IV setiap 8-12 jam. Pantau kadar terendah (trough). Infus lambat untuk mencegah sindrom red man."}}},{id:"co-amoxiclav",genericName:"Amoxicillin / Clavulanate",brandNames:["Augmentin","Claneksi","Co-amoxiclav OGB"],drugClass:"Penicillin + Beta-lactamase inhibitor",indications:{en:"Bite wounds, otitis media, sinusitis, lower respiratory infections.",id:"Luka gigitan, otitis media, sinusitis, infeksi saluran napas bawah."},contraindications:{en:"History of amoxicillin/clavulanate-associated hepatic dysfunction.",id:"Riwayat disfungsi hati terkait amoksisilin/klavulanat."},dosing:{dosePerKg:45,unit:"mg",maxDose:2e3,frequency:"q12h or q8h",notes:{en:"Dosed based on amoxicillin component. High risk of diarrhea.",id:"Dosis berdasarkan komponen amoksisilin. Risiko tinggi diare."}}},{id:"cotrimoxazole",genericName:"Trimethoprim / Sulfamethoxazole",brandNames:["Bactrim","Septra","Sanprima"],drugClass:"Sulfonamide Antibiotic",indications:{en:"Uncomplicated UTI, PCP pneumonia prophylaxis/treatment, MRSA (some).",id:"ISK tanpa komplikasi, profilaksis/pengobatan pneumonia PCP, MRSA (beberapa)."},contraindications:{en:"Megaloblastic anemia due to folate deficiency, infants < 2 months.",id:"Anemia megaloblastik akibat defisiensi folat, bayi < 2 bulan."},dosing:{dosePerKg:8,unit:"mg",maxDose:960,frequency:"q12h",notes:{en:"Dose based on Trimethoprim component. Can cause Stevens-Johnson Syndrome.",id:"Dosis berdasarkan komponen Trimetoprim. Dapat menyebabkan Sindrom Stevens-Johnson."}}},{id:"gentamicin",genericName:"Gentamicin",brandNames:["Garamycin","Sagestam","Gentamicin OGB"],drugClass:"Aminoglycoside Antibiotic",indications:{en:"Severe gram-negative infections, endocarditis synergy.",id:"Infeksi gram negatif berat, sinergi endokarditis."},contraindications:{en:"Hypersensitivity to aminoglycosides.",id:"Hipersensitivitas terhadap aminoglikosida."},dosing:{dosePerKg:5,unit:"mg",maxDose:500,frequency:"q24h",notes:{en:"5-7 mg/kg IV once daily (extended interval). Nephrotoxic and ototoxic.",id:"5-7 mg/kg IV sekali sehari (interval diperpanjang). Nefrotoksik dan ototoksik."}}},{id:"piperacillin-tazobactam",genericName:"Piperacillin / Tazobactam",brandNames:["Zosyn","Tazocin"],drugClass:"Antipseudomonal Penicillin + Beta-lactamase inhibitor",indications:{en:"Severe intra-abdominal infections, nosocomial pneumonia, sepsis.",id:"Infeksi intra-abdomen berat, pneumonia nosokomial, sepsis."},contraindications:{en:"Severe hypersensitivity to penicillins or cephalosporins.",id:"Hipersensitivitas berat terhadap penisilin atau sefalosporin."},dosing:{dosePerKg:100,unit:"mg",maxDose:16e3,frequency:"q6h or q8h",notes:{en:"Adults: 4.5g IV q6h. Adjust in renal impairment.",id:"Dewasa: 4.5g IV setiap 6 jam. Sesuaikan pada gangguan ginjal."}}},{id:"cefepime",genericName:"Cefepime",brandNames:["Maxipime","Fepime"],drugClass:"4th Generation Cephalosporin",indications:{en:"Severe nosocomial pneumonia, febrile neutropenia, complicated UTI.",id:"Pneumonia nosokomial berat, neutropenia febris, ISK terkomplikasi."},contraindications:{en:"Hypersensitivity to cephalosporins.",id:"Hipersensitivitas terhadap sefalosporin."},dosing:{dosePerKg:50,unit:"mg",maxDose:6e3,frequency:"q8h or q12h",notes:{en:"Adults: 1-2g IV q8-12h. Risk of neurotoxicity (encephalopathy) in renal failure.",id:"Dewasa: 1-2g IV setiap 8-12 jam. Risiko neurotoksisitas pada gagal ginjal."}}},{id:"linezolid",genericName:"Linezolid",brandNames:["Zyvox","Linox"],drugClass:"Oxazolidinone Antibiotic",indications:{en:"VRE infections, complicated skin infections, MRSA pneumonia.",id:"Infeksi VRE, infeksi kulit terkomplikasi, pneumonia MRSA."},contraindications:{en:"Concurrent use of MAO inhibitors within 14 days.",id:"Penggunaan bersamaan inhibitor MAO dalam 14 hari."},dosing:{dosePerKg:10,unit:"mg",maxDose:1200,frequency:"q12h",notes:{en:"Adults: 600 mg IV/PO q12h. Risk of serotonin syndrome and myelosuppression.",id:"Dewasa: 600 mg IV/PO setiap 12 jam. Risiko sindrom serotonin dan mielosupresi."}}},{id:"fluconazole",genericName:"Fluconazole",brandNames:["Diflucan","Cryptal","Fluconazole OGB"],drugClass:"Triazole Antifungal",indications:{en:"Candidiasis (oropharyngeal, esophageal, vaginal, systemic), cryptococcal meningitis.",id:"Kandidiasis (orofaringeal, esofageal, vaginal, sistemik), meningitis kriptokokus."},contraindications:{en:"Coadministration with terfenadine or QT-prolonging drugs.",id:"Pemberian bersama terfenadin atau obat yang memperpanjang QT."},dosing:{dosePerKg:6,unit:"mg",maxDose:800,frequency:"q24h",notes:{en:"Loading dose often required. Adjust in renal impairment. Hepatotoxic.",id:"Dosis muatan sering diperlukan. Sesuaikan pada gangguan ginjal. Hepatotoksik."}}},{id:"acyclovir",genericName:"Acyclovir",brandNames:["Zovirax","Clinovir","Acyclovir OGB"],drugClass:"Antiviral",indications:{en:"Herpes simplex, varicella zoster, herpes zoster.",id:"Herpes simpleks, varicella zoster (cacar air), herpes zoster (cacar ular)."},contraindications:{en:"Hypersensitivity to acyclovir or valacyclovir.",id:"Hipersensitivitas terhadap asiklovir atau valasiklovir."},dosing:{dosePerKg:10,unit:"mg",maxDose:4e3,frequency:"q8h (IV) or 5x/day (PO)",notes:{en:"Adequate hydration needed to prevent crystalline nephropathy (especially IV).",id:"Hidrasi memadai diperlukan untuk mencegah nefropati kristalin (terutama IV)."}}},{id:"cefazolin",genericName:"Cefazolin",brandNames:["Ancef","Kefzol","Cefazolin OGB"],drugClass:"1st Generation Cephalosporin",indications:{en:"Surgical prophylaxis, skin/soft tissue infections, MSSA infections.",id:"Profilaksis bedah, infeksi kulit/jaringan lunak, infeksi MSSA."},contraindications:{en:"Severe hypersensitivity to cephalosporins or penicillins.",id:"Hipersensitivitas berat terhadap sefalosporin atau penisilin."},dosing:{dosePerKg:25,unit:"mg",maxDose:2e3,frequency:"q8h",notes:{en:"Adults: 1-2g IV every 8 hours. Commonly used for surgical prophylaxis (dose given 60 mins before incision).",id:"Dewasa: 1-2g IV setiap 8 jam. Umum digunakan untuk profilaksis bedah (dosis diberikan 60 menit sebelum insisi)."}}},{id:"cephalexin",genericName:"Cephalexin",brandNames:["Keflex","Ceporex"],drugClass:"1st Generation Cephalosporin",indications:{en:"Uncomplicated skin/soft tissue infections, streptococcal pharyngitis, uncomplicated UTI.",id:"Infeksi kulit/jaringan lunak tanpa komplikasi, faringitis streptokokus, ISK tanpa komplikasi."},contraindications:{en:"Severe hypersensitivity to cephalosporins.",id:"Hipersensitivitas berat terhadap sefalosporin."},dosing:{dosePerKg:15,unit:"mg",maxDose:1e3,frequency:"q6h or q12h",notes:{en:"Adults: 250-500 mg PO q6h or 500 mg PO q12h. Adjust in renal impairment.",id:"Dewasa: 250-500 mg PO setiap 6 jam atau 500 mg PO setiap 12 jam. Sesuaikan pada gangguan ginjal."}}},{id:"cefadroxil",genericName:"Cefadroxil",brandNames:["Duricef","Cefat","Lapicef"],drugClass:"1st Generation Cephalosporin",indications:{en:"Pharyngitis, tonsillitis, skin/soft tissue infections, UTI.",id:"Faringitis, tonsilitis, infeksi kulit/jaringan lunak, ISK."},contraindications:{en:"Severe hypersensitivity to cephalosporins.",id:"Hipersensitivitas berat terhadap sefalosporin."},dosing:{dosePerKg:15,unit:"mg",maxDose:1e3,frequency:"q12h or q24h",notes:{en:"Adults: 500 mg - 1g PO q12h or 1g PO q24h. Take with food if GI upset occurs.",id:"Dewasa: 500 mg - 1g PO setiap 12 jam atau 1g PO setiap 24 jam. Konsumsi bersama makanan jika perut mual."}}},{id:"cefuroxime",genericName:"Cefuroxime",brandNames:["Zinacef","Ceftin","Sharox","Celocin"],drugClass:"2nd Generation Cephalosporin",indications:{en:"Respiratory tract infections, otitis media, Lyme disease, surgical prophylaxis.",id:"Infeksi saluran pernapasan, otitis media, penyakit Lyme, profilaksis bedah."},contraindications:{en:"Severe hypersensitivity to cephalosporins.",id:"Hipersensitivitas berat terhadap sefalosporin."},dosing:{dosePerKg:15,unit:"mg",maxDose:1500,frequency:"q8h (IV) or q12h (PO)",notes:{en:"Adults: 250-500 mg PO q12h; 750 mg - 1.5g IV q8h. Better gram-negative coverage than 1st gen.",id:"Dewasa: 250-500 mg PO setiap 12 jam; 750 mg - 1.5g IV setiap 8 jam. Cakupan gram-negatif lebih baik daripada gen 1."}}},{id:"cefaclor",genericName:"Cefaclor",brandNames:["Ceclor","Cloracef"],drugClass:"2nd Generation Cephalosporin",indications:{en:"Otitis media, lower respiratory tract infections, skin infections, UTI.",id:"Otitis media, infeksi saluran napas bawah, infeksi kulit, ISK."},contraindications:{en:"Severe hypersensitivity to cephalosporins.",id:"Hipersensitivitas berat terhadap sefalosporin."},dosing:{dosePerKg:10,unit:"mg",maxDose:500,frequency:"q8h",notes:{en:"Adults: 250-500 mg PO q8h. Serum sickness-like reactions are more common with Cefaclor.",id:"Dewasa: 250-500 mg PO setiap 8 jam. Reaksi mirip serum sickness lebih umum pada Cefaclor."}}},{id:"cefoxitin",genericName:"Cefoxitin",brandNames:["Mefoxin"],drugClass:"2nd Generation Cephamycin (grouped with Cephalosporins)",indications:{en:"Surgical prophylaxis (GI/biliary/pelvic), intra-abdominal infections, PID.",id:"Profilaksis bedah (GI/bilier/pelvis), infeksi intra-abdomen, penyakit radang panggul (PID)."},contraindications:{en:"Severe hypersensitivity to cephalosporins.",id:"Hipersensitivitas berat terhadap sefalosporin."},dosing:{dosePerKg:20,unit:"mg",maxDose:2e3,frequency:"q6h or q8h",notes:{en:"Adults: 1-2g IV q6-8h. Strong coverage against anaerobes (e.g., Bacteroides).",id:"Dewasa: 1-2g IV setiap 6-8 jam. Cakupan kuat terhadap anaerob (mis., Bacteroides)."}}}]}};